#include <cstdint>
#include <functional>
#include <unordered_map>

struct Symbol {
    std::uint16_t exchange;
    std::uint32_t id;

    bool operator==(const Symbol&) const = default;
};

template <>
struct std::hash<Symbol> {
    std::size_t operator()(const Symbol& symbol) const noexcept {
        const auto h1 = std::hash<std::uint16_t>{}(symbol.exchange);
        const auto h2 = std::hash<std::uint32_t>{}(symbol.id);
        return h1 * 0x9e3779b1U ^ h2;
    }
};

void use_symbol_map() {
    std::unordered_map<Symbol, double> prices;
    prices.emplace(Symbol{7, 42}, 101.25);
}

#include <functional>
#include <map>
#include <string>
#include <string_view>

using Counts = std::map<std::string, int, std::less<>>;

void ensure(Counts& counts, std::string_view key) {
    counts.try_emplace(std::string{key}, 0);
}

bool overwrite(Counts& counts, std::string_view key, int value) {
    auto [position, inserted] =
        counts.insert_or_assign(std::string{key}, value);
    (void)position;
    return inserted;  // true means a new key, false means an update
}

void bump(Counts& counts, std::string_view key) {
    auto found = counts.find(key);  // transparent: no temporary string
    if (found != counts.end()) {
        ++found->second;
    }
}

