void print_range(const std::map<std::string, int>& counts,
                 const std::string& low,
                 const std::string& high) {
    const auto first = counts.lower_bound(low);   // first key >= low
    const auto last = counts.lower_bound(high);   // first key >= high

    for (auto it = first; it != last; ++it) {
        std::cout << it->first << ": " << it->second << '\n';
    }
}

#include <iostream>
#include <unordered_map>

bool fill_without_rehash(std::unordered_map<int, int>& values,
                         int count) {
    values.reserve(static_cast<std::size_t>(count));  // elements, not buckets
    const auto prepared = values.bucket_count();

    for (int key = 0; key < count; ++key) {
        values.emplace(key, key);
    }

    // Even here, holding an iterator across the loop would be a bad habit:
    // any insertion that exceeded max_load_factor() would rehash, and a
    // rehash invalidates every iterator (though pointers and references to
    // elements survive, because the nodes are relinked rather than moved).
    return values.bucket_count() == prepared;
}

#include <cstdint>
#include <flat_map>
#include <optional>
#include <utility>
#include <vector>

using Rows = std::vector<std::pair<std::uint32_t, int>>;
using Limits = std::flat_map<std::uint32_t, int>;

Limits build_limits(const Rows& rows) {
    // One bulk construction: O(n log n) sorting, one pair of allocations.
    // Inserting the rows one at a time would shift a tail each time, O(n^2).
    return Limits(rows.begin(), rows.end());
}

std::optional<int> limit_for(const Limits& limits, std::uint32_t id) {
    // O(log n) binary search over contiguous keys: no dependent node loads.
    const auto found = limits.find(id);
    if (found == limits.end()) {
        return std::nullopt;
    }
    return found->second;
}

#include <map>
#include <string>
#include <utility>

bool rename(std::map<std::string, int>& books,
            const std::string& from,
            const std::string& to) {
    auto node = books.extract(from);
    if (node.empty()) {
        return false;  // nothing by that name
    }

    node.key() = to;  // legal: the node is outside the tree
    auto result = books.insert(std::move(node));

    if (!result.inserted) {
        // result.node still owns the element; put it back under its old key
        // so the rename fails without losing data.
        result.node.key() = from;
        books.insert(std::move(result.node));
        return false;
    }
    return true;
}
